import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'package:meta/meta.dart';
import 'dart:io';

import 'package:path_provider/path_provider.dart';
import 'package:path/path.dart' as p;

import 'tables.dart';

part 'app_database.g.dart';

/// Main Drift database — all 15 local tables.
///
/// Code generated by `dart run build_runner build`.
@DriftDatabase(
  tables: [
    // Cache tables
    CachedTemplates,
    CachedGroups,
    CachedCriteria,
    CachedStores,
    CachedSubmissions,
    CachedActionPlans,
    CachedNotifications,
    CachedPolicies,
    CachedGlobalRisks,
    // Outbox tables
    PendingSubmissions,
    PendingAnswers,
    PendingPhotos,
    PendingActionPlanUpdates,
    SubmissionRiskOutboxEntries,
    // Metadata
    SyncMeta,
    // Drafts
    DraftAnswers,
  ],
)
class AppDatabase extends _$AppDatabase {
  AppDatabase() : super(_openConnection());

  /// For testing — accepts a custom executor.
  AppDatabase.forTesting(super.e);

  @override
  int get schemaVersion => 21;

  @override
  MigrationStrategy get migration => MigrationStrategy(
    onCreate: (Migrator m) async {
      await m.createAll();
      await _createVoidTriggers(customStatement);
    },
    onUpgrade: (Migrator m, int from, int to) async {
      if (from < 2) {
        await m.addColumn(cachedStores, cachedStores.areaId);
        await m.addColumn(cachedStores, cachedStores.areaName);
      }
      if (from < 3) {
        await m.addColumn(cachedGroups, cachedGroups.minusPerFault);
      }
      if (from < 4) {
        await m.createTable(draftAnswers);
      }
      if (from < 5) {
        await m.addColumn(
          cachedSubmissions,
          cachedSubmissions.templateSnapshot,
        );
        await m.addColumn(cachedSubmissions, cachedSubmissions.templateVersion);
      }
      if (from < 6) {
        await m.addColumn(cachedActionPlans, cachedActionPlans.storeId);
      }
      if (from < 7) {
        // Void Audits (Slice 4)
        await m.addColumn(cachedSubmissions, cachedSubmissions.voidReason);
        await m.addColumn(cachedSubmissions, cachedSubmissions.voidedAt);
        await m.addColumn(cachedActionPlans, cachedActionPlans.rootCause);

        await _createVoidTriggers(customStatement);
      }
      if (from < 8) {
        // Pillar C: add answerId to pending_photos for server-side answer patching.
        await m.addColumn(pendingPhotos, pendingPhotos.answerId);
      }
      if (from < 9) {
        // Pillar D: SQLite-backed exponential backoff columns.
        await m.addColumn(pendingSubmissions, pendingSubmissions.retryCount);
        await m.addColumn(pendingSubmissions, pendingSubmissions.nextRetryAt);
        await m.addColumn(pendingPhotos, pendingPhotos.retryCount);
        await m.addColumn(pendingPhotos, pendingPhotos.nextRetryAt);
      }
      if (from < 10) {
        // P1 UX: Store Manager offline evidence queue.
        await m.createTable(pendingActionPlanUpdates);
      }
      if (from < 11) {
        // PBAC Slice 4: local capability cache — persists across app restarts.
        await m.createTable(cachedPolicies);
      }
      if (from < 12) {
        // Orphaned Resume fix: track the server's submission ID for finalize routing.
        await m.addColumn(
          pendingSubmissions,
          pendingSubmissions.targetSubmissionId,
        );
      }
      if (from < 13) {
        // Score Verification fix: persist repeat fault count for accurate server-side scoring.
        await m.addColumn(pendingAnswers, pendingAnswers.repeatedFaults);
      }
      if (from < 14) {
        // Auditor Manual Override fix: persist answer-level RISK/CCP overrides.
        await m.addColumn(pendingAnswers, pendingAnswers.isCcp);
        await m.addColumn(pendingAnswers, pendingAnswers.isRisk);
      }
      if (from < 15) {
        // Action Plan Audit Trail: add evidence submission fields.
        await m.addColumn(
          cachedActionPlans,
          cachedActionPlans.evidenceSubmittedAt,
        );
        await m.addColumn(
          cachedActionPlans,
          cachedActionPlans.evidenceSubmittedByName,
        );
      }
      if (from < 16) {
        // Audit Category Filters: add template_type snapshot column.
        await m.addColumn(cachedSubmissions, cachedSubmissions.templateType);
      }
      if (from < 17) {
        // Score Mismatch fix: add minusImpact to CachedCriteria table for checklist deductions.
        await m.addColumn(cachedCriteria, cachedCriteria.minusImpact);
      }
      if (from < 18) {
        // Slice 4: Global Risks offline sync tables.
        await m.createTable(cachedGlobalRisks);
        await m.createTable(submissionRiskOutboxEntries);
      }
      if (from < 20) {
        // Phase 1B Visual Folders: criterion-level deduction cap.
        await m.addColumn(cachedCriteria, cachedCriteria.maxDeductionPoints);
      }
      if (from < 21) {
        // Evidence Photo Uploads: local path persistence for offline uploads.
        await m.addColumn(
          pendingActionPlanUpdates,
          pendingActionPlanUpdates.photoPath,
        );
      }
    },
    beforeOpen: (details) async {
      // GC: silently prune stale audits on every DB open.
      // Errors swallowed — a GC failure must NEVER crash startup.
      try {
        await _pruneStaleAudits();
      } catch (e) {
        // ignore: avoid_print
        print('[GC] pruneStaleAudits failed: $e');
      }
    },
  );

  static Future<void> _createVoidTriggers(
    void Function(String) executor,
  ) async {
    // AFTER UPDATE trigger: Handles status changes for existing submissions.
    executor('''
      CREATE TRIGGER IF NOT EXISTS tr_void_submissions_update
      AFTER UPDATE ON cached_submissions 
      WHEN NEW.status = 'voided'
      BEGIN
        UPDATE cached_action_plans 
        SET status = 'closed', root_cause = 'SYSTEM_VOID' 
        WHERE submission_id = NEW.id AND status != 'closed';
      END;
    ''');

    // AFTER INSERT trigger: Handles new submissions (synced deltas) that arrive as voided.
    executor('''
      CREATE TRIGGER IF NOT EXISTS tr_void_submissions_insert
      AFTER INSERT ON cached_submissions 
      WHEN NEW.status = 'voided'
      BEGIN
        UPDATE cached_action_plans 
        SET status = 'closed', root_cause = 'SYSTEM_VOID' 
        WHERE submission_id = NEW.id AND status != 'closed';
      END;
    ''');
  }

  // ── GC: 90-day TTL pruning ──

  Future<void> _pruneStaleAudits() async {
    // Drift stores DateTime as INTEGER (seconds since Unix epoch unless configured otherwise).
    // Instead of doing column math `/ 1000` in SQL causing full table scans,
    // we evaluate the 90-day cutoff in Dart and pass it as a bind variable.
    // This allows SQLite to use indexes on `completed_at` and `voided_at`.
    final cutoffSeconds =
        DateTime.now()
            .subtract(const Duration(days: 90))
            .millisecondsSinceEpoch ~/
        1000;

    // 1. Delete linked action plans first (FK child-before-parent ordering).
    await customStatement(
      '''
      DELETE FROM cached_action_plans
      WHERE submission_id IN (
        SELECT id FROM cached_submissions
        WHERE (status = 'completed' AND completed_at < ?)
           OR (status = 'voided'    AND voided_at   < ?)
      )
    ''',
      [cutoffSeconds, cutoffSeconds],
    );

    // 2. Delete stale submissions.
    await customStatement(
      '''
      DELETE FROM cached_submissions
      WHERE (status = 'completed' AND completed_at < ?)
         OR (status = 'voided'    AND voided_at   < ?)
    ''',
      [cutoffSeconds, cutoffSeconds],
    );
  }

  /// Public testing entry point. Do NOT call from production code.
  /// Prevents Mirror Function Trap — tests call this rather than duplicating SQL.
  @visibleForTesting
  Future<void> pruneStaleAuditsForTesting() => _pruneStaleAudits();

  /// WIPE: Thoroughly cleans the entire Drift offline cache.
  /// Used by AuthManager during logout to prevent cross-session data bleeding.
  Future<void> clearAllData() async {
    await transaction(() async {
      for (final table in allTables) {
        await delete(table).go();
      }
    });
  }
}

LazyDatabase _openConnection() {
  return LazyDatabase(() async {
    final dir = await getApplicationDocumentsDirectory();
    final file = File(p.join(dir.path, 'checkly_local.db'));
    return NativeDatabase.createInBackground(
      file,
      setup: (db) {
        // Diagnostic check for JSON1 extension (required for JSONB columns)
        try {
          db.execute("SELECT json_valid('{}')");
        } catch (e) {
          throw Exception(
            'FATAL: Compiled sqlite3 binary is missing JSON1 extension support. $e',
          );
        }
      },
    );
  });
}
